$title A Transportation Problem (TRNSPORT)
* Classic Dantzig (1963) least-cost shipping LP

Sets
  i   canning plants   / seattle, san-diego /
  j   markets          / new-york, chicago, topeka / ;

Parameters
  a(i)  capacity of plant i in cases
    / seattle    350
      san-diego  600 /
  b(j)  demand at market j in cases
    / new-york   325
      chicago    300
      topeka     275 / ;

Table d(i,j)  distance in thousands of miles
                  new-york  chicago  topeka
  seattle            2.5      1.7     1.8
  san-diego          2.5      1.8     1.4 ;

Scalar f  freight in dollars per case per thousand miles / 90 / ;
Parameter c(i,j)  transport cost in thousands of dollars per case ;
c(i,j) = f * d(i,j) / 1000 ;

Variables
  x(i,j)  shipment quantities in cases
  z       total transportation costs in thousands of dollars ;
Positive Variable x ;

Equations
  cost        define objective function
  supply(i)   observe supply limit at plant i
  demand(j)   satisfy demand at market j ;

cost..        z  =e=  sum((i,j), c(i,j)*x(i,j)) ;
supply(i)..   sum(j, x(i,j))  =l=  a(i) ;
demand(j)..   sum(i, x(i,j))  =g=  b(j) ;

Model transport / all / ;
Solve transport using lp minimizing z ;
Display x.l, x.m, z.l ;

$title Petroleum Refinery Crude Processing and Blending LP
Sets
  cr  crude oils       / wti, brent, heavy /
  pr  refined products / gasoline, diesel, jetfuel / ;

Parameters
  crCost(cr)  crude purchase and refining cost USD per bbl
    / wti    74.0
      brent  78.5
      heavy  66.0 /
  crCap(cr)   crude availability in kbbl per day
    / wti    120
      brent  100
      heavy   80 /
  prPrice(pr) product selling price USD per bbl
    / gasoline 98.0
      diesel   94.0
      jetfuel  96.0 /
  prMax(pr)   market demand ceiling in kbbl per day
    / gasoline 110
      diesel    95
      jetfuel   65 / ;

Table yield(cr,pr)  fractional distillation yield
             gasoline  diesel  jetfuel
  wti          0.45     0.30    0.20
  brent        0.40     0.35    0.20
  heavy        0.25     0.40    0.22 ;

Scalar distCap  total atmospheric distillation capacity in kbbl per day / 220 / ;

Variables
  run(cr)   crude processed in kbbl per day
  sell(pr)  product sold in kbbl per day
  profit    net daily operating margin in kUSD per day ;
Positive Variables run, sell ;

run.up(cr)  = crCap(cr) ;
sell.up(pr) = prMax(pr) ;

Equations
  obj        maximize net margin
  cduCap     crude distillation unit capacity
  matBal(pr) product material balance ;

obj..        profit =e= sum(pr, prPrice(pr)*sell(pr)) - sum(cr, crCost(cr)*run(cr)) ;
cduCap..     sum(cr, run(cr)) =l= distCap ;
matBal(pr).. sell(pr) =l= sum(cr, yield(cr,pr)*run(cr)) ;

Model refinery / all / ;
Solve refinery using lp maximizing profit ;
Display run.l, sell.l, profit.l ;

$title Thermal Power Plant Unit Commitment MILP
$include gen_data.inc

Sets
  g  thermal generators / g1, g2, g3 /
  t  time periods       / t1*t4 / ;

Parameters
  pmin(g)   minimum generation in MW         / g1 50,  g2 30,  g3 20 /
  pmax(g)   maximum generation in MW         / g1 200, g2 150, g3 100 /
  varC(g)   variable fuel cost USD per MWh   / g1 28,  g2 36,  g3 48 /
  fixC(g)   no-load commitment USD per hr    / g1 400, g2 280, g3 180 /
  load(t)   hourly system demand in MW       / t1 180, t2 290, t3 340, t4 240 / ;

Variables
  p(g,t)    power dispatch in MW
  u(g,t)    unit commitment binary status
  z         total operating cost in USD ;
Positive Variable p ;
Binary Variable u ;

Equations
  cost          total commitment and dispatch cost
  balance(t)    system power balance
  minOut(g,t)   generator minimum stable output
  maxOut(g,t)   generator maximum capacity ;

cost..         z =e= sum((g,t), fixC(g)*u(g,t) + varC(g)*p(g,t)) ;
balance(t)..   sum(g, p(g,t)) =g= load(t) ;
minOut(g,t)..  p(g,t) =g= pmin(g)*u(g,t) ;
maxOut(g,t)..  p(g,t) =l= pmax(g)*u(g,t) ;

Model unit_commit / all / ;
Solve unit_commit using mip minimizing z ;
Display u.l, p.l, z.l ;

